import{_ as a,C as o,o as n,c as i,j as p,a as r,E as l,a5 as d}from"./chunks/framework.DNkHA0lr.js";const k=JSON.parse('{"title":"你不需要细分领域，你需要一个观点","description":"","frontmatter":{"title":"你不需要细分领域，你需要一个观点","originalTitle":"You don’t need a niche, you need a point of view","date":"2025-07-31","originalUrl":"https://thedankoe.com/letters/you-dont-need-a-niche-you-need-a-point-of-view/","minutes":8,"sourceHash":"7077c85d6337f1022b468b64b205b95b936d0935f77df31a98a4fb6457151019","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-dont-need-a-niche-you-need-a-point-of-view/"}]]},"headers":[],"relativePath":"letters/you-dont-need-a-niche-you-need-a-point-of-view.md","filePath":"letters/you-dont-need-a-niche-you-need-a-point-of-view.md"}'),s={name:"letters/you-dont-need-a-niche-you-need-a-point-of-view.md"};function m(c,e,h,u,f,b){const t=o("ArticleMeta");return n(),i("div",null,[e[0]||(e[0]=p("h1",{id:"你不需要细分领域-你需要一个观点",tabindex:"-1"},[r("你不需要细分领域，你需要一个观点 "),p("a",{class:"header-anchor",href:"#你不需要细分领域-你需要一个观点","aria-label":'Permalink to "你不需要细分领域，你需要一个观点"'},"​")],-1)),l(t),e[1]||(e[1]=d('<p>如果你是一名作家、创作者、自由职业者，或是任何正试图在有意义的事情上“做出成绩”的人，你大概都在社交媒体上。如果你不在，那你或者已经有一套适合自己的方法（这封信不适用于你），或者就是在浪费时间，应该去社交媒体上折腾一下。</p><p>问题是，大多数创作者已经变成了内容工厂。</p><p>美化过的搜索引擎。</p><p>在一个任何人只需点一下按钮就能找到任何信息的时代，他们成了专业知识的存储库。</p><p>大多数创作者一事无成，因为他们说的话、说话的方式、以及为什么这么说，都没有什么特别之处。他们没有能推动别人改变想法或采取行动的<em>观点</em>。他们所拥有的，只是一些看起来已经被说过千百次的无聊建议。</p><p>在互联网还年轻、还空空如也的时候，选择一个细分领域曾经是很好的建议。</p><p>但就像历史上其他任何类型的专家一样，他们是最容易被取代的那群人。如果你的内容策略可以写成纸上的一系列步骤——调研点子、构思内容主题、使用特定的内容框架——那任何人都能搭一个AI虚拟形象，随便哪一天都能把你比下去。</p><p>好消息是，那99%的内容根本没有任何去处。直接沉到桶底。那些担心AI会制造出无穷内容的人，根本不明白顶尖1%的创作者为什么能做得这么好。</p><p>这是因为，人们不会关注字典，他们关注的是人。</p><p>他们想要的是原始的观点。他们想要清晰，胜过想要信息。他们想要故事和戏剧性。</p><p>他们想要一个观点。</p><h3 id="最赚钱的细分领域就是你自己" tabindex="-1">最赚钱的细分领域就是你自己 <a class="header-anchor" href="#最赚钱的细分领域就是你自己" aria-label="Permalink to &quot;最赚钱的细分领域就是你自己&quot;">​</a></h3><blockquote><p>用真实性来逃避竞争。——纳瓦尔</p></blockquote><p>每次我告诉人们，他们可以谈论多个兴趣，而且这样做要好得多的时候，他们都会理所当然地感到担忧。</p><p>每一条关于人生和商业的建议都告诉他们要“专注于一件事”，但他们没意识到，他们的兴趣并不是一堆互不相关的想法。害怕自己显得分散，反而阻碍了人们发现自己无可取代之处的过程。</p><p>我们来拆解一下。我会尽力把它讲清楚，然后附上一些你可以在自己的工作中尝试的实用做法。</p><p>你的经历塑造了你是谁。也就是你的身份。</p><p>你的身份由目标和价值观构成。是那些你认为重要的东西。</p><p>你的目标和价值观塑造了你的观点。也就是你过滤具体信息的方式，这又会影响你做出的决定，而这些决定又反过来强化你的身份。</p><p>你的观点是无法被复制的，因为没有人能获得那一整套将你的大脑塑造成今天这般独特模样的环境刺激序列。</p><p>当你从一个专业知识的存储库转变为一个人们借以观察世界的透镜时，你就成了跨越不同领域的众多想法的<em>策展人</em>，并将它们综合到<em>一个</em>作品体系之下。你不再拥有某个类别或话题，你拥有的是一种视角，这种视角创造出一组独特的、相互关联的想法群，因为它们经过了你独特的价值观、经历和目标的过滤，所以无法被复制。</p><p>就是这样。</p><p>人们不会对一本字典产生情感连接。相反，他们会被那些拥有相似世界观的人吸引，愿意去关注。你担心人们不想关注你，是因为他们不喜欢你谈论的某个具体兴趣，但你每次刷社交媒体的时候，都会划过成百上千种不同的兴趣。</p><p>我不谈论比特币或加密货币之类的东西，但无论你对此感兴趣还是不感兴趣，我都可以保证，我能写出一篇有说服力的、基于故事的帖子，让你们中的很多人（以及网上一些随机的人）对它产生兴趣。</p><p>而且，你天生并没有什么兴趣。你是被说服相信它们的重要性，然后它们才<em>变得</em>对你有趣。这就是我<a href="https://letters.thedankoe.com/p/full-guide-how-i-write-about-deep?lli=1" target="_blank" rel="noreferrer">写深刻的想法却依然能半病毒式传播</a>的方法。</p><p>无法谈论任何你想谈的兴趣，那是技能问题。</p><h3 id="有机的新颖-vs-人为制造的新颖" tabindex="-1">有机的新颖 VS 人为制造的新颖 <a class="header-anchor" href="#有机的新颖-vs-人为制造的新颖" aria-label="Permalink to &quot;有机的新颖 VS 人为制造的新颖&quot;">​</a></h3><blockquote><p>动物无法选择自己的目标。它们的目标（自我保存和繁衍）可以说是预先设定好的。它们的成功机制仅限于这些内置的目标图像，我们称之为“本能”。而人类则拥有动物所没有的东西：创造性想象力。因此，人类比其他任何生物都更胜一筹，他不仅是一种生物，也是一个创造者。凭借想象力，他能设定出各种各样的目标。唯有人类能通过运用想象力，即造像能力，来引导自己的成功机制。——马克斯韦尔·马尔茨</p></blockquote><p>不管你喜不喜欢，注意力是靠新颖性驱动的，如果你无法吸引注意力，你的独立工作就不可能取得半点成功。</p><p>最成功的创作者都是多巴胺贩子。</p><p>但这不意味着你必须制造戏剧性、使用操纵手段来强迫人们关注你。这意味着你需要<em>分享一些新东西。</em></p><p>当你自己就是细分领域时，你就是在公众面前真实的自己。大多数人以为真实性意味着以某种模糊、感觉良好的方式“做自己”，但真实性其实是与从众相反的东西。真实性不是去顺从别人告诉你“最好”的某个特定“细分领域”，只为了赚钱。从这个意义上说，真实性实际上就是你的内容策略。它意味着让你的世界观来决定你谈论什么。</p><p>创造出新颖或新鲜的东西，归根到底靠的是模式识别。</p><p>模式识别与生存和身份紧密相连。当我们的祖先狩猎时，多巴胺会向他们的大脑发出信号，表明某个机会值得关注，比如植物上新长出的浆果，或森林里猎物的声音。</p><p>现在，你不必再为寻找食物而发愁了（除了杂货店和Uber Eats其实是模拟且高度优化的“狩猎场”），但同样的事情仍在你的大脑中发生。当你带着“学习如何赚钱”这个目标去读一本书时，书中的想法就会呈现出这种形态。你会注意到<em>新</em>的想法，如果你从同样的视角把它们分享给网上的人们，他们就会接触到一个抓住注意力的新想法。如果你带着“变得更幸福”这个目标去读同一本书，你就会从中注意到不同的想法。</p><p>这就像一种哲学上的折射。正如光线穿过不同的介质会发生变化一样，<em>想法在穿过不同的观点时也会发生转变。</em></p><p>换句话说，成为一名更好的创作者，其实就是拥有一个有意义的目标，然后分享那些让你兴奋的想法。这是以兴奋为先的内容创作，比追逐潮流要充实得多。</p><p>举个例子，如果你对“复利”这个概念感到着迷，你可能会从积累财富的角度去谈论它。但当另一个人谈论它时，它会被折射进他们的世界观，他们可能会从习惯养成的角度来谈论它。詹姆斯·克利尔（James Clear）的“每天进步1%”理念之所以能吸引这么多关注，正是出于这个原因。他把一个古老的想法，通过自己独特的思维方式重新框定，让它变得焕然一新。</p><p>这就是为什么一种观点是无法被复制的。</p><p>AI可以复述任何想法，但它<em>无法</em>通过它并不存在的、亲身经历过的哲学，把这个想法折射向一个它自主选择的目标。</p><h3 id="注意力经济-vs-关怀经济" tabindex="-1">注意力经济 VS 关怀经济 <a class="header-anchor" href="#注意力经济-vs-关怀经济" aria-label="Permalink to &quot;注意力经济 VS 关怀经济&quot;">​</a></h3><p>在阿德勒心理学中，有一个“生活方式”（lifestyle）的概念。</p><p>不是我们通常理解的那种生活方式（汽车、房子、假期），而是你对生活的根本取向。是你用来应对存在的那套无意识的信念、目标和策略蓝图。它在早年就已形成，<em>并成为你解读一切事物的透镜。</em></p><p>到目前为止，我们已经明白，你的观点<em>就是</em>你独一无二的细分领域，而分享那些让你兴奋的想法，是你以一种可持续的方式（且不必出卖灵魂）创造新颖性的方法。</p><p>拼图的最后一块，是你的个人愿景。</p><p>你理想中的生活方式。</p><p>正是这个东西把一切串联起来，将你分享的所有内容统一到一个<em>品牌</em>之下，因为品牌就是随着时间推移，人们把你和什么联系在一起。</p><p>你理想的生活方式是你的北极星。也就是说，如果你想在未来的工作中取得成功，你不能只是坐着无所作为。你必须把事业的成长和个人的成长融合在一起。你真的必须<em>去做点什么，</em>而正是这种“去做”让你能够发现值得与他人分享的想法，帮助他们做类似的事情，因为这些想法与他们的目标和价值观产生了共鸣。</p><p>正是这一点，让人们<em>在乎</em>你，而不是把你当作一条可以随手划过、转眼就忘的信息。人们会记住你。人们会想买你的东西。人们在乎那些改变了他们人生的人，而你改变他们人生的方式，就是提供一整套作品，改变他们的思考方式，从而改变他们是谁、他们如何行动——最好是朝着一个压倒性的好结果去改变。关于这一点，我写过一篇指南，<a href="https://letters.thedankoe.com/p/how-to-build-a-world-the-2-hour-content?lli=1" target="_blank" rel="noreferrer">如何通过内容生态系统构建一个世界</a>。</p><p>当你在追求一种你真正在乎的生活，并分享那些让你感兴趣的想法时，你的内容就会带有一种能量印记。更多的坚定，更多的清晰。人们能感觉到这一点。他们喜爱你的作品，因为在每一个想法里，他们都会感觉自己在学到某种<em>新</em>的东西，可以被吸纳成为他们自己世界观的一部分。</p><p>为了让这一点变得具体，并给你一些可以尝试的东西：</p><ul><li>不要专注于某个话题，专注于<em>你</em>认为对实现理想生活方式重要的一切</li><li>把从书籍、视频、播客、文章等地方收集到的有趣想法，作为每日的研究习惯策展下来（记下让你兴奋的东西）</li><li>把这些想法作为短内容发布出去，把你的社交主页当作你的笔记平台</li><li>每周从这些想法中挑一个最有意思的，写成一篇长文通讯或视频</li><li>在这篇长内容里，填满个人经历、相关想法，以及具体可行的收获</li></ul><p>如果你在第一步就卡住了，不知道自己理想的生活方式是什么……</p><p>那么，你需要审视你的生活。你需要<em>始终</em>思考自己想要和不想要过什么样的生活，否则你就不是在带着意识和意图生活。你是在梦游。</p><p>这就是你需要做的全部。清晰感会自己浮现。</p><p>每天思考自己想要什么、不想要什么，哪怕只是很简单的一个动作（试试去散步，只专注想这件事），慢慢地就会形成一种观点。</p><p>然后，你就能做出决定，注意到那些能让你远离不想要的东西、走向你想要的东西的想法。</p><p>希望这封信对你有帮助。</p><p>——丹</p><hr><p><a href="/en/letters/you-dont-need-a-niche-you-need-a-point-of-view">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',61))])}const y=a(s,[["render",m]]);export{k as __pageData,y as default};
